const int N = (int)2e5 + 100;

vector<int> g[N];
char used[N];

void addEdge(int v, int u) {
	g[v].push_back(u);
	g[u].push_back(v);
}

void dfs(int v) {
	used[v] = 1;

	for (int to : g[v]) {
		if (!used[to]) {
			dfs(to);
		}
	}
}

